343	    private String extractAuthor(String secondTitle) {
344	        String result = null;
345	
346	        if (secondTitle != null) {
347	            secondTitle = secondTitle.replace(TERTIARY_TEXT_DELIM + " LIVE", ""); // remove special marks
348	            String[] split = secondTitle.split(TERTIARY_TEXT_DELIM);
349	
350	            if (split.length <= 1) {
351	                result = secondTitle;
352	            } else {
353	                // First part may be a special label (4K, Stream, New etc)
354	                // Two cases to detect label: 1) Description is long (4 items); 2) First item of info is too short (2 letters)
355	                //result = split.length < 4 && split[0].trim().length() > 2 ? split[0] : split[1];
356	                result = split.length < 4 ? split[0] : split[1];
357	            }
358	        }
359	
360	        // Skip subtitles starting with number of views (e.g. 1.4M views). Usually found in channel uploads.
361	        return !TextUtils.isEmpty(result) && (!belongsToChannelUploads() || !Helpers.isNumeric(result.substring(0, 1))) ? result.trim() : null;
362	    }
