382	    public static Video fromString(String spec) {
383	        if (spec == null) {
384	            return null;
385	        }
386	
387	        String[] split = Helpers.splitObj(spec);
388	
389	        // 'playlistParams' backward compatibility
390	        if (split.length == 10) {
391	            split = Helpers.appendArray(split, new String[]{null});
392	        }
393	
394	        // 'extra' backward compatibility
395	        if (split.length == 11) {
396	            split = Helpers.appendArray(split, new String[]{"-1"});
397	        }
398	
399	        // 'reloadPageKey' backward compatibility
400	        if (split.length == 12) {
401	            split = Helpers.appendArray(split, new String[]{null});
402	        }
403	
404	        // 'type' backward compatibility
405	        if (split.length == 13) {
406	            split = Helpers.appendArray(split, new String[]{"-1"});
407	        }
408	
409	        if (split.length == 14) {
410	            split = Helpers.appendArray(split, new String[]{null});
411	        }
412	
413	        if (split.length == 15) {
414	            split = Helpers.appendArray(split, new String[]{null});
415	        }
416	
417	        if (split.length == 16) {
418	            split = Helpers.appendArray(split, new String[]{"-1"});
419	        }
420	
421	        if (split.length == 17) {
422	            split = Helpers.appendArray(split, new String[]{null});
423	        }
424	
425	        if (split.length == 18) {
426	            split = Helpers.appendArray(split, new String[]{null});
427	        }
428	
429	        if (split.length == 19) {
430	            split = Helpers.appendArray(split, new String[]{null});
431	        }
432	
433	        if (split.length == 20) {
434	            split = Helpers.appendArray(split, new String[]{"false"});
435	        }
436	
437	        if (split.length == 21) {
438	            split = Helpers.appendArray(split, new String[]{"-1"});
439	        }
440	
441	        if (split.length == 22) {
442	            split = Helpers.appendArray(split, new String[]{null});
443	        }
444	
445	        if (split.length != 23) {
446	            return null;
447	        }
448	
449	        Video result = new Video();
450	
451	        result.id = Helpers.parseInt(split[0]);
452	        result.category = Helpers.parseStr(split[1]);
453	        result.title = Helpers.parseStr(split[2]);
454	        result.videoId = Helpers.parseStr(split[3]);
455	        //result.videoUrl = Helpers.parseStr(split[4]);
456	        result.playlistId = Helpers.parseStr(split[5]);
457	        result.channelId = Helpers.parseStr(split[6]);
458	        result.bgImageUrl = Helpers.parseStr(split[7]);
459	        result.cardImageUrl = Helpers.parseStr(split[8]);
460	        //result.mediaItem = YouTubeMediaItem.deserializeMediaItem(Helpers.parseStr(split[9]));
461	        result.playlistParams = Helpers.parseStr(split[10]);
462	        result.sectionId = Helpers.parseInt(split[11]);
463	        result.reloadPageKey = Helpers.parseStr(split[12]);
464	        result.itemType = Helpers.parseInt(split[13]);
465	        result.secondTitle = Helpers.parseStr(split[14]);
466	        result.previewUrl = Helpers.parseStr(split[15]);
467	        result.percentWatched = Helpers.parseFloat(split[16]);
468	        result.metadataTitle = Helpers.parseStr(split[17]);
469	        result.metadataSecondTitle = Helpers.parseStr(split[18]);
470	        result.badge = Helpers.parseStr(split[19]);
471	        result.isLive = Helpers.parseBoolean(split[20]);
472	        result.channelGroupId = Helpers.parseStr(split[21]);
473	        result.searchQuery = Helpers.parseStr(split[22]);
474	
475	        // Reset old type (int)
476	        if (Helpers.equals(result.channelGroupId, "-1")) {
477	            result.channelGroupId = null;
478	        }
479	
480	        return result;
481	    }
