601	    public boolean belongsToSameAuthorGroup() {
602	        if (getGroup() == null || getGroup().getSize() < 2) {
603	            return false;
604	        }
605	
606	        Video first = getGroup().get(0);
607	        Video last = getGroup().get(getGroup().getSize() - 1);
608	
609	        String author1 = extractAuthor(first.getSecondTitle());
610	        String author2 = extractAuthor(last.getSecondTitle());
611	
612	        return author1 != null && author2 != null && Helpers.equals(author1, author2);
613	    }
