615	    public boolean belongsToSamePlaylistGroup() {
616	        if (getGroup() == null || getGroup().getSize() < 2) {
617	            return false;
618	        }
619	
620	        // Some items may not have a playlistId (e.g. movies)
621	        List<Video> filtered = Helpers.filter(getGroup().getVideos(), item -> item.getPlaylistId() != null || item.playlistParams != null, 2);
622	
623	        if (filtered == null || filtered.size() < 2) {
624	            return false;
625	        }
626	
627	        Video first = filtered.get(0);
628	        Video second = filtered.get(1);
629	
630	        String playlist1 = first.getPlaylistId() != null ? first.getPlaylistId() : first.playlistParams;
631	        String playlist2 = second.getPlaylistId() != null ? second.getPlaylistId() : second.playlistParams;
632	
633	        return playlist1 != null && playlist2 != null && Helpers.equals(playlist1, playlist2);
634	    }
