846	    private MediaItem findNextVideo(MediaItemMetadata metadata) {
847	        if (metadata == null) {
848	            return null;
849	        }
850	
851	        MediaItem nextVideo = metadata.getNextVideo();
852	
853	        // BUGFIX: player closed after last video from the remote queue
854	        if (nextVideo == null && isRemote) {
855	            List<MediaGroup> suggestions = metadata.getSuggestions();
856	
857	            if (suggestions != null && suggestions.size() > 1) {
858	                List<MediaItem> mediaItems = suggestions.get(1).getMediaItems();
859	                BlockedChannelData blockedChannelData = BlockedChannelData.instance(GlobalPreferences.context());
860	                nextVideo = Helpers.findFirst(mediaItems,
861	                        item -> {
862	                            if (blockedChannelData.isEmpty()) {
863	                                return item.getVideoId() != null;
864	                            }
865	
866	                            Video video = Video.from(item);
867	                            return video != null
868	                                    && video.videoId != null && !blockedChannelData.containsChannel(video.channelId, video.getAuthor());
869	                        });
870	            }
871	        }
872	
873	        return nextVideo;
874	    }
