        if (split.length == 18) split = appendArray(split, new String[]{null});
        if (split.length == 19) split = appendArray(split, new String[]{null});
        if (split.length == 20) split = appendArray(split, new String[]{"false"});
        if (split.length == 21) split = appendArray(split, new String[]{"-1"});
        if (split.length == 22) split = appendArray(split, new String[]{null});
        if (split.length != 23) return null;
        return split;
    }

    static final int FIELD_COUNT = 23;
    static final int FIRST_LEGACY_FIELD = 10;
    static final String[] LEGACY_FIELD_DEFAULTS = {
        null,"-1",null,"-1",null,null,"-1",null,null,null,"false","-1",null };

    // NEW logic
    static String[] newLogic(String[] split) {
        if (split.length >= FIRST_LEGACY_FIELD && split.length < FIELD_COUNT) {
            String[] missing = Arrays.copyOfRange(
                LEGACY_FIELD_DEFAULTS, split.length - FIRST_LEGACY_FIELD, LEGACY_FIELD_DEFAULTS.length);
            split = appendArray(split, missing);
        }
        if (split.length != FIELD_COUNT) return null;
        return split;
    }

    public static void main(String[] a) {
        boolean ok = true;
        for (int len = 0; len <= 26; len++) {
            String[] base = new String[len];
            for (int i = 0; i < len; i++) base[i] = "f" + i; // distinct real values
            String[] o = oldLogic(base.clone());
            String[] n = newLogic(base.clone());
            boolean eq = Arrays.equals(o, n);
            if (!eq) { ok = false; System.out.println("MISMATCH len=" + len + " old=" + Arrays.toString(o) + " new=" + Arrays.toString(n)); }
            else System.out.println("len=" + len + " OK -> " + (o == null ? "null" : "len" + o.length + " " + Arrays.toString(o)));
        }
        System.out.println(ok ? "ALL EQUIVALENT" : "FAILED");
    }
}
